def find_in_ring(ring, targets):
    n = len(ring)
    lo, hi = 0, n - 1
    while lo < hi:  # find the smallest id
        mid = (lo + hi) // 2
        if ring[mid] > ring[hi]:
            lo = mid + 1
        else:
            hi = mid
    start = lo
    out = []
    for t in targets:
        a, b = 0, n  # search the sorted order, read from start
        while a < b:
            m = (a + b) // 2
            if ring[(start + m) % n] < t:
                a = m + 1
            else:
                b = m
        k = (start + a) % n if n else 0
        out.append(k if a < n and ring[k] == t else -1)
    return out

